import os,re,collections
root='AlgebraicJacobian'
imports={}
for dp,_,fns in os.walk(root):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn)
            mod=p[:-5].replace('/','.')
            deps=set()
            for line in open(p,encoding='utf8',errors='replace'):
                m=re.match(r'import\s+(AlgebraicJacobian[\w.]*)',line)
                if m: deps.add(m.group(1))
                if line.strip() and not line.startswith(('import','/-','-','*',' ')) and 'import' not in line:
                    pass
            imports[mod]=deps
Q='AlgebraicJacobian.Picard.QuotScheme'
GQ='AlgebraicJacobian.Picard.GrassmannianQuot'
def reaches(start, target, banned=None):
    # returns a path or None
    seen={start}; stack=[(start,[start])]
    while stack:
        n,path=stack.pop()
        for d in imports.get(n,()):
            if banned and (n,d)==banned: continue
            if d==target: return path+[d]
            if d not in seen:
                seen.add(d); stack.append((d,path+[d]))
    return None
deps4=['AlgebraicJacobian.Picard.GrassmannianZariskiSheaf','AlgebraicJacobian.Picard.GrassmannianRepresentability','AlgebraicJacobian.Picard.SerreTwist','AlgebraicJacobian.Picard.ScalarEndFaithful']
print("Does each dependent still reach QuotScheme if the GrassmannianQuot->QuotScheme edge is cut?")
for d in deps4:
    p=reaches(d,Q,banned=(GQ,Q))
    print(f"  {d.split('.')[-1]:32s} -> {'YES via ' + ' -> '.join(x.split('.')[-1] for x in p) if p else 'NO (prune would decouple it)'}")
print()
# how many modules reach QuotScheme at all, and only via GrassmannianQuot?
allmods=list(imports)
onlyvia=[]
still=[]
for m in allmods:
    if m in (Q,): continue
    a=reaches(m,Q)
    if not a: continue
    b=reaches(m,Q,banned=(GQ,Q))
    if b is None: onlyvia.append(m)
    else: still.append(m)
print(f"modules reaching QuotScheme: {len(onlyvia)+len(still)}   decoupled by the prune: {len(onlyvia)}   unaffected: {len(still)}")
print("decoupled:", [x.split('.')[-1] for x in onlyvia])
